mapper.sql:
where q.deleted = false
  and q.question_type = #{request.questionType}

    and q.level = #{request.level}


    and q.difficulty = #{request.difficulty}


    and q.spoken = #{request.spoken}


    and q.business = #{request.business}


    and q.exam = #{request.exam}


    and q.source_type = #{request.sourceType}


    and q.enabled = #{request.enabled}


    and exists (
        select 1
        from question_tags qt
        inner join tags t on t.id = qt.tag_id
        where qt.question_id = q.id
          and t.deleted = false
          and t.enabled = true
          and t.code in

              #{code}

    )

mapper.select:
select q.id
from questions q

order by q.created_at desc, q.id desc
limit #{limit}
offset #{offset}

mapper.update:
update questions
set
    enabled = #{enabled},
    updated_at = #{updatedAt}
where id = #{id}
  and deleted = false
